import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { home, isWindows, platform } from './paths.js';

export const BEGIN = '# >>> azure-multiprofile >>>';
export const END = '# <<< azure-multiprofile <<<';
export const SHELLS = ['zsh', 'bash', 'fish', 'pwsh'];

/** The one line each rc file sources. Everything else is generated by `init` at shell start. */
export function blockBody(shell) {
  switch (shell) {
    case 'zsh':
    case 'bash':
      return `command -v azure-multiprofile >/dev/null 2>&1 && eval "$(azure-multiprofile init ${shell})"`;
    case 'fish':
      return 'type -q azure-multiprofile; and azure-multiprofile init fish | source';
    case 'pwsh':
      return 'if (Get-Command azure-multiprofile -ErrorAction SilentlyContinue) { Invoke-Expression (& azure-multiprofile init pwsh | Out-String) }';
    default:
      throw new Error(`Unsupported shell "${shell}". Supported: ${SHELLS.join(', ')}.`);
  }
}

export function renderBlock(shell) {
  return [BEGIN, '# Managed by azure-multiprofile. Edits inside this block are overwritten.', blockBody(shell), END].join('\n');
}

/** Returns [{ start, end }] line ranges (inclusive) of every managed block. */
export function findBlocks(content) {
  const lines = content.split('\n');
  const blocks = [];
  let start = -1;
  lines.forEach((line, i) => {
    const t = line.trim();
    if (t === BEGIN && start === -1) start = i;
    else if (t === END && start !== -1) {
      blocks.push({ start, end: i, text: lines.slice(start, i + 1).join('\n') });
      start = -1;
    }
  });
  return blocks;
}

/**
 * Insert or replace the managed block, leaving every other line untouched.
 * Duplicates collapse into the first block's position.
 */
export function upsertBlock(content, block) {
  const blocks = findBlocks(content);
  if (blocks.length === 0) {
    const sep = content === '' || content.endsWith('\n') ? '' : '\n';
    return `${content}${sep}${block}\n`;
  }
  const lines = content.split('\n');
  const out = [];
  let i = 0;
  blocks.forEach((b, idx) => {
    out.push(...lines.slice(i, b.start));
    if (idx === 0) out.push(...block.split('\n'));
    i = b.end + 1;
  });
  out.push(...lines.slice(i));
  return out.join('\n');
}

export function removeBlocks(content) {
  const blocks = findBlocks(content);
  if (blocks.length === 0) return content;
  const lines = content.split('\n');
  const drop = new Set();
  for (const b of blocks) for (let i = b.start; i <= b.end; i++) drop.add(i);
  return lines.filter((_, i) => !drop.has(i)).join('\n');
}

let pwshProfileCache;
function pwshProfilePath() {
  if (process.env.AZMP_PWSH_PROFILE) return process.env.AZMP_PWSH_PROFILE;
  if (pwshProfileCache !== undefined) return pwshProfileCache;
  pwshProfileCache = null;
  if (!process.env.AZMP_HOME) {
    // Ask pwsh itself: the Documents folder may be redirected (OneDrive) on Windows.
    const r = spawnSync('pwsh', ['-NoProfile', '-NonInteractive', '-Command', '$PROFILE.CurrentUserCurrentHost'], {
      encoding: 'utf8',
      timeout: 10000,
    });
    const out = r.status === 0 ? r.stdout.trim() : '';
    if (out) pwshProfileCache = out;
  }
  if (!pwshProfileCache) {
    pwshProfileCache = isWindows()
      ? path.join(home(), 'Documents', 'PowerShell', 'Microsoft.PowerShell_profile.ps1')
      : path.join(home(), '.config', 'powershell', 'Microsoft.PowerShell_profile.ps1');
  }
  return pwshProfileCache;
}

export function rcFileFor(shell) {
  switch (shell) {
    case 'zsh':
      return path.join(process.env.AZMP_HOME ? home() : process.env.ZDOTDIR || home(), '.zshrc');
    case 'bash':
      // macOS terminals start login shells, which read .bash_profile rather than .bashrc.
      return path.join(home(), platform() === 'darwin' ? '.bash_profile' : '.bashrc');
    case 'fish':
      return path.join(
        process.env.AZMP_HOME ? path.join(home(), '.config') : process.env.XDG_CONFIG_HOME || path.join(home(), '.config'),
        'fish',
        'config.fish',
      );
    case 'pwsh':
      return pwshProfilePath();
    default:
      throw new Error(`Unsupported shell "${shell}". Supported: ${SHELLS.join(', ')}.`);
  }
}

export function readFileOr(file, fallback = '') {
  try {
    return fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return fallback;
    throw err;
  }
}

/** Status of the managed block in one shell's rc file. */
export function inspectShell(shell) {
  const file = rcFileFor(shell);
  const content = readFileOr(file, null);
  if (content === null) return { shell, file, exists: false, blocks: 0, current: false };
  const blocks = findBlocks(content);
  return {
    shell,
    file,
    exists: true,
    blocks: blocks.length,
    current: blocks.length === 1 && blocks[0].text.trim() === renderBlock(shell),
  };
}

export function installShell(shell) {
  const file = rcFileFor(shell);
  const before = readFileOr(file);
  const after = upsertBlock(before, renderBlock(shell));
  if (after === before) return { file, changed: false };
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, after);
  return { file, changed: true };
}

export function uninstallShell(shell) {
  const file = rcFileFor(shell);
  const before = readFileOr(file, null);
  if (before === null) return { file, changed: false };
  const after = removeBlocks(before);
  if (after === before) return { file, changed: false };
  fs.writeFileSync(file, after);
  return { file, changed: true };
}

/** Best guess at the user's interactive shell. */
export function currentShell() {
  if (process.env.AZMP_SHELL && SHELLS.includes(process.env.AZMP_SHELL)) return process.env.AZMP_SHELL;
  if (process.env.PSModulePath && isWindows()) return 'pwsh';
  const base = path.basename(process.env.SHELL || '');
  if (SHELLS.includes(base)) return base;
  return isWindows() ? 'pwsh' : 'bash';
}
